runtime.setup_command:
&{
  $ErrorActionPreference = 'Stop'
  cd $HOME
  $null = mkdir -Force llama-cuda
  cd .\llama-cuda

  $assets = @(
    @{ name = 'cudart-llama-bin-win-cuda-13.5-x64.zip'; sha256 = 'c2bf4cc202bfbaaa7a0b75f5082457c3811326947bb216059b72839d844e9cba' },
    @{ name = 'llama-b12387-bin-win-cuda-13.5-x64.zip'; sha256 = '451b353723c8ef9788ed0b6757010500f01d89ffac6f9d7dc910997847f0361d' }
  )

  foreach ($asset in $assets) {
    $url = "https://github.com/ggml-org/llama.cpp/releases/download/b12387/$($asset.name)"
    Invoke-WebRequest -Uri $url -OutFile $asset.name
    $actual = (Get-FileHash -Algorithm SHA256 -LiteralPath $asset.name).Hash.ToLower()
    if ($actual -ne $asset.sha256) {
      $assets | ForEach-Object { Remove-Item -LiteralPath $_.name -Force -ErrorAction SilentlyContinue }
      throw "Checksum mismatch for $($asset.name): expected $($asset.sha256), got $actual. The downloads were deleted and nothing was extracted."
    }
  }

  foreach ($asset in $assets) {
    Expand-Archive $asset.name .\llama -Force
  }

  cd .\llama
  $env:PATH = "$PWD;$env:PATH"
}

